// Bounded portable presentation owner. No singleton, gameplay state, fetch override or persistent storage.
import{prepareForestPlayer,isAuthoritativeForestPlayer}from'../native/recovery_runtime_20261102/s5_resume/dist/development/hakdong-forest-native/player.mjs';
import{prepareStaticNineNpcRenderer}from'./npc-renderer.mjs';
const fail=code=>{throw Error(code)},owners=new WeakMap();
export const isActorPool=pool=>owners.get(pool)?.()===true;
export function createActorPool(){
 const entries=new Map(),errors=[],ownerAbort=new AbortController();let dead=false,serial=0,resolveClosed;const closed=new Promise(resolve=>resolveClosed=resolve);
 const settleClosed=()=>{if(dead&&entries.size===0)resolveClosed()};
 function closeEntry(entry){if(entry.value){const value=entry.value;entry.value=null;try{value.dispose()}catch(e){errors.push(String(e?.message??e))}}entry.state='closed';if(entries.get(entry.key)===entry)entries.delete(entry.key);settleClosed()}
 function get(key){
  if(dead)fail('ACTOR_POOL_DISPOSED');const old=entries.get(key);if(old){if(old.abandoned)fail('ACTOR_POOL_DRAINING');return old}
  const entry={key,id:++serial,refs:0,state:'pending',value:null,abandoned:false,controller:new AbortController(),promise:null};entries.set(key,entry);
  // Defer external preparation until the caller has registered its reference.
  entry.promise=Promise.resolve().then(async()=>{
   if(dead||entry.abandoned)fail('ACTOR_POOL_CANCELLED');
   const value=key==='npcs'?await prepareStaticNineNpcRenderer({signal:entry.controller.signal}):await prepareForestPlayer({appearance:key.slice(7),signal:entry.controller.signal});
   entry.value=value;
   if(dead||entry.abandoned||key!=='npcs'&&!isAuthoritativeForestPlayer(value)){closeEntry(entry);fail('ACTOR_POOL_CANCELLED')}
   entry.state='ready';return value;
  }).catch(error=>{closeEntry(entry);throw error});
  entry.promise.catch(()=>{});return entry;
 }
 function releaseEntry(entry){if(entry.refs<1)fail('ACTOR_POOL_REFCOUNT');entry.refs--;if(entry.refs!==0)return;if(entry.state==='pending'){entry.abandoned=true;entry.controller.abort()}else if(dead)closeEntry(entry)}
 async function acquire(options={}){
  if(!options||Object.getPrototypeOf(options)!==Object.prototype)fail('ACTOR_POOL_OPTIONS');for(const k of Reflect.ownKeys(options)){const d=Object.getOwnPropertyDescriptor(options,k);if(!['appearance','signal'].includes(k)||!d?.enumerable||!Object.hasOwn(d,'value'))fail('ACTOR_POOL_OPTIONS')}
  const{appearance,signal}=options;if(!['boy','girl'].includes(appearance)||signal!==undefined&&!(signal instanceof AbortSignal))fail('ACTOR_POOL_INPUT');if(dead)fail('ACTOR_POOL_DISPOSED');if(signal?.aborted)fail('ACTOR_POOL_ABORTED');
  const held=[];let released=false,rejectAbort;
  function release(){if(released)return;released=true;signal?.removeEventListener('abort',abort);ownerAbort.signal.removeEventListener('abort',abort);for(const entry of held)releaseEntry(entry)}
  const aborted=new Promise((_,reject)=>{rejectAbort=reject});aborted.catch(()=>{});
  function abort(){release();rejectAbort(Error('ACTOR_POOL_ABORTED'))}
  signal?.addEventListener('abort',abort,{once:true});ownerAbort.signal.addEventListener('abort',abort,{once:true});
  try{
   const playerEntry=get('player:'+appearance);playerEntry.refs++;held.push(playerEntry);
   const npcEntry=get('npcs');npcEntry.refs++;held.push(npcEntry);
   const[player,npcs]=await Promise.race([Promise.all([playerEntry.promise,npcEntry.promise]),aborted]);
   if(dead||released||signal?.aborted)fail('ACTOR_POOL_ABORTED');
   ownerAbort.signal.removeEventListener('abort',abort);
   return Object.freeze({player,npcs,release,get released(){return released},appearance});
  }catch(error){release();throw error}
 }
 function dispose(){if(dead)return;dead=true;ownerAbort.abort();for(const entry of entries.values()){if(entry.state==='pending'){entry.abandoned=true;entry.controller.abort()}else if(entry.refs===0)closeEntry(entry)}settleClosed()}
 const api=Object.freeze({acquire,dispose,closed,get diagnostics(){return Object.freeze({disposed:dead,maxEntries:3,maxDecodedBitmaps:18,entries:Object.freeze([...entries.values()].map(e=>Object.freeze({key:e.key,id:e.id,state:e.state,refs:e.refs,draining:e.abandoned}))),cleanupErrors:Object.freeze([...errors])})}});owners.set(api,()=>!dead);return api;
}

// Read-only UI-boundary intent prototype. No execution or persistence capability.
import{evaluateStoryExpression}from'../canonical/story/gates.mjs';
import{enhancedLeagueActive}from'../canonical/story/enhanced-league.mjs';
import{activeEconomyPolicy,quotePurchase,validateEconomyState}from'../canonical/economy/contract.mjs';
import{sha256,stableJSON}from'../canonical/compatibility/codec.mjs';
import{worldStageAccess}from'../canonical/world/state.mjs';
const EVENTS=new Set(['S7_NEST_THREAT','S7_SEA_ACCESS','S8_MARINE_EXPANSION','S8_CAPTURE_SHIP']);
const RIVALS=new Set(['RIVAL_04','RIVAL_05']);
const LOCKS=['worldPending','storyBusy','storyPendingCommit','fieldInputLocked','coreLock','coreSequence','corePendingBattle','dialogue'];
const result=(status,reason,extra={})=>Object.freeze({status,reason,...extra,runtimeActivation:false,effects:0});
export function captureLiveContext(world){return{mapId:world.map.id,worldPending:!!world.pending,storyBusy:!!world.story.busy,storyPendingCommit:!!world.story.pendingCommit,fieldInputLocked:!!world.inputLocked,coreLock:!!world.field.core.lock,coreSequence:!!world.field.core.sequence,corePendingBattle:!!world.field.core.pendingBattle,dialogue:!!world.field.dialogue.length};}
// Exact coordinate-independent subset of private #eventReady and trainerAvailable.
// Original enhancedLeague/gate evaluator reused; only 4 events and 2 rivals admitted.
export function eventReady(s,c,id){const e=c.events[id],p=s.progress;if(enhancedLeagueActive(s))return false;return !!e?.active&&!e.acquisitionOnly&&e.stageId===p.currentStage&&!p.completedEvents.includes(id)&&e.requiresEvents.every(x=>p.completedEvents.includes(x))&&e.requiresGates.every(x=>evaluateStoryExpression(x,s,c))&&(id!=='FINAL_LEAGUE'||p.leagueWins.length===4);}
export function rivalReady(s,c,id){const t=c.trainers[id],p=s.progress;if(enhancedLeagueActive(s)||!t||!RIVALS.has(id)||t.stageId!==p.currentStage||!s.party.some(m=>m.hp>0)||!worldStageAccess(s,c,t.stageId)||p.defeatedTrainers.includes(id)&&!t.repeatable)return false;if(t.eventId&&!eventReady(s,c,t.eventId))return false;return true;}
export function createSemanticAdmission({catalog,definition,contract,verifyProximity=()=>false}){
 if(!catalog||!definition?.points||!contract?.events)throw Error('TRUSTED_SOURCE_REQUIRED');
 function inspect({pointId,action={},snapshot:s,liveContext:live,proximity}){try{
  const p=definition.points[pointId];if(!p||!['world:hub:S7','world:hub:S8'].includes(p.mapId))return result('DENIED','UNKNOWN_OR_OUT_OF_SCOPE_POINT');
  // Caller supplies a proof returned by the separately bound spatial inspector, not a bare true.
  if(verifyProximity(proximity)!==true||proximity?.revision!==s?.revision||!proximity||proximity.pointId!==pointId||proximity.mapId!==p.mapId||proximity.allowed!==true)return result('DENIED','PROXIMITY');
  if(!live||live.mapId!==p.mapId||LOCKS.some(k=>typeof live[k]!=='boolean'))return result('DENIED','LIVE_CONTEXT_REQUIRED');
  if(LOCKS.some(k=>live[k]))return result('DENIED','UI_LOCKED');
  if(!s||s.contentNamespace!=='canonical-v1'||s.world?.mapId!==p.mapId||s.world?.version!==definition.version||!s.progress||!Array.isArray(s.party))return result('DENIED','SEMANTIC_CONTEXT_REQUIRED');
  const progress=s.progress;
  if(!Number.isSafeInteger(s.revision)||s.revision<0||!contract.stages[progress.currentStage]||!progress.flags||!progress.items||!s.inventory||['completedEvents','completedStages','defeatedTrainers','badges','leagueWins'].some(k=>!Array.isArray(progress[k])||progress[k].some(v=>typeof v!=='string'))||Object.keys(contract.flags).some(k=>typeof progress.flags[k]!=='boolean')||s.party.some(m=>!m||!Number.isSafeInteger(m.hp)||m.hp<0))return result('DENIED','INCOMPLETE_SEMANTIC_CONTEXT');
  if(progress.completedStages.some(id=>!contract.stages[id])||progress.completedEvents.some(id=>!contract.events[id])||progress.defeatedTrainers.some(id=>!contract.trainers[id])||[...Object.values(progress.items),...Object.values(s.inventory)].some(n=>!Number.isSafeInteger(n)||n<0))return result('DENIED','INVALID_SEMANTIC_IDENTITIES_OR_ITEMS');
  validateEconomyState(s,catalog);
  if(catalog.economyPolicy?.id==='ECONOMY_CAPTURE_APPROVED_V1'&&!activeEconomyPolicy(s,catalog))return result('DENIED','SESSION_ECONOMY_NOT_NORMALIZED');
  if(!worldStageAccess(s,contract,definition.maps[p.mapId].stageId))return result('DENIED','MAP_STAGE_LOCKED');
  if(enhancedLeagueActive(s))return result('DENIED','ENHANCED_LEAGUE_ACTIVE');
  if(p.kind==='event'){
   const id=contract.aliases[p.eventId]??p.eventId;if(!EVENTS.has(id))return result('DENIED','UNSUPPORTED_EVENT');
   if(s.progress.completedEvents.includes(id))return result('IDEMPOTENT_INTENT','EVENT_ALREADY_COMPLETED',{eventId:id});
   const e=contract.events[id];if(!eventReady(s,contract,id)||e.trainerId&&!rivalReady(s,contract,e.trainerId))return result('DENIED','EVENT_UNAVAILABLE');
   return result('ADMISSIBLE_INTENT','RUN_EVENT',{eventId:id});
  }
  if(p.kind==='trainer'){
   const id=p.trainerId,t=contract.trainers[id];if(!RIVALS.has(id)||!t)return result('DENIED','UNSUPPORTED_TRAINER');
   if(!t.repeatable&&s.progress.defeatedTrainers.includes(id))return result('IDEMPOTENT_INTENT','TRAINER_AFTER_DIALOGUE',{trainerId:id});
   return rivalReady(s,contract,id)?result('ADMISSIBLE_INTENT','RUN_TRAINER',{trainerId:id}):result('DENIED','TRAINER_UNAVAILABLE');
  }
  if(!['heal','shop'].includes(p.kind))return result('DENIED','UNSUPPORTED_KIND');
  if(p.kind==='heal'&&action.type&&action.type!=='heal')return result('DENIED','UNSUPPORTED_CENTER_ACTION');
  const enabled=activeEconomyPolicy(s,catalog);
  if(!enabled){if(p.kind==='shop'){quotePurchase(s,catalog.itemContract,action.itemId,action.quantity);return result('DENIED','ECONOMY_POLICY_PENDING');}return result('ADMISSIBLE_INTENT','VISIT_THEN_RECOVER_NOT_ATOMIC');}
  // New read-only shop-opening intent: original UI entry precedes item selection.
  if(p.kind==='shop'&&action.type==='open-shop'){if(!proximity.facilityVerified)return result('DENIED','FACILITY_GEOMETRY_UNVERIFIED');if(p.stageId&&!s.progress.completedStages.includes(p.stageId)&&s.progress.currentStage!==p.stageId)return result('DENIED','FACILITY_STAGE');return result('ADMISSIBLE_INTENT','OPEN_SHOP');}
  const request=p.kind==='shop'?{type:'purchase',transactionId:action.transactionId,hubId:p.hubId,itemId:action.itemId,quantity:action.quantity}:{type:'heal',transactionId:action.transactionId,hubId:p.hubId};
  const id=request.transactionId;if(typeof id!=='string'||!id.trim()||id.length>160)return result('DENIED','TRANSACTION_ID');
  const old=s.economy.transactions[id];if(old){if(old.fingerprint!==sha256(stableJSON(request)))return result('DENIED','TRANSACTION_CONFLICT');return result('IDEMPOTENT_INTENT','CACHED_RECEIPT_NO_NEW_EFFECT',{transactionId:id});}
  // Geometric validLanding/atHub are deliberately separate proof responsibilities.
  if(!proximity.facilityVerified)return result('DENIED','FACILITY_GEOMETRY_UNVERIFIED');
  if(p.stageId&&!s.progress.completedStages.includes(p.stageId)&&s.progress.currentStage!==p.stageId)return result('DENIED','FACILITY_STAGE');
  if(p.kind==='shop'){const q=quotePurchase(s,catalog.itemContract,action.itemId,action.quantity,{unlimited:true,approved:catalog.economyPolicy.id==='ECONOMY_CAPTURE_APPROVED_V1',hubId:p.hubId});if(s.economy.money<q.cost)return result('DENIED','INSUFFICIENT_MONEY');return result('ADMISSIBLE_INTENT','PURCHASE',{quote:q});}
  return result('ADMISSIBLE_INTENT','VISIT_THEN_ECONOMY_HEAL_NOT_ATOMIC');
 }catch(e){return result('DENIED','SOURCE_VALIDATION_REJECTED',{detail:String(e.message)});}}
 return Object.freeze({inspect});
}

