// DEV Map controls only. Host owns installation; this module never imports browser storage.
export function mountDevCheckpointDOM({root,host,pause=()=>{},resume=()=>{},events=globalThis,document=root.ownerDocument}){
 const save=root.querySelector('[data-checkpoint-save]'),load=root.querySelector('[data-checkpoint-load]'),status=root.querySelector('[data-checkpoint-status]'),cancelButton=root.querySelector('[data-checkpoint-cancel]');if(!save||!load||!status||!cancelButton)throw Error('CHECKPOINT_DOM_REQUIRED');let dead=false,busy=false,epoch=0;const off=[];
