export function safe(state,x,y,bits=0){if(!STATES.includes(state)||!point(x,y)||!Number.isSafeInteger(bits)||bits<0||bits>7||x<24||y<18||x+24>=1448||y+18>=1086)return false;const body=actorFeet(bits);for(let yy=y-18;yy<=y+18;yy++)for(let xx=x-24;xx<=x+24;xx++){if(!rawAt(state,xx,yy)||body.some(([ax,ay])=>xx>=ax-24&&xx<ax+25&&yy>=ay-18&&yy<ay+19))return false}return true;}
// Explicit preparation only, never at module import. Derived raw is not a PNG and not eroded.
export function deriveNoNpcRaw(state){if(!STATES.includes(state))throw Error('GYM8_STATE');const raw=new Uint8Array(1448*1086);for(let y=0;y<1086;y++)for(let x=0;x<1448;x++)raw[y*1448+x]=+rawAt(state,x,y);return raw;}
export function camera(x,y){if(!Number.isFinite(x)||!Number.isFinite(y))throw Error('GYM8_CAMERA_FOOT');return Object.freeze([Math.max(0,Math.min(488,Math.round(x-480))),Math.max(0,Math.min(546,Math.round(y-270))),960,540]);}

import{ACTORS}from'../gym8/connection/actor-data.mjs';
import{SOURCE}from'../gym8/payload/poison-gym8-native/source-data.mjs';
const FETCH=globalThis.fetch?.bind(globalThis),DECODE=globalThis.createImageBitmap?.bind(globalThis);
const BASE=new URL('../',import.meta.url);
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function prepareGym8SimulationActors({signal}={}){
 const images=new Map();let dead=false,pending=null;const closed=new WeakSet();
 const close=im=>{if(im&&!closed.has(im)){closed.add(im);try{im.close()}catch{}}};
 const dispose=()=>{if(dead)return;dead=true;signal?.removeEventListener('abort',dispose);for(const im of images.values())close(im);images.clear()};
 const check=()=>{if(dead||signal?.aborted)throw Error('GYM8_ACTORS_DISPOSED')};
 signal?.addEventListener('abort',dispose,{once:true});
 try{check();if(!FETCH||!DECODE)throw Error('GYM8_ACTOR_BROWSER_INPUTS');for(const a of ACTORS){
  const r=await FETCH(new URL('gym8/connection/assets/'+a.identity+'.png',BASE),{signal});if(!r.ok)throw Error('GYM8_ACTOR_EXACT_ASSET_MISSING');const bytes=await r.arrayBuffer();check();if(await hash(bytes)!==a.atlas.sha256)throw Error('GYM8_ACTOR_PIN');pending=await DECODE(new Blob([bytes]));check();if(pending.width!==a.atlas.width||pending.height!==a.atlas.height)throw Error('GYM8_ACTOR_SIZE');images.set(a.id,pending);pending=null;
 }
 return Object.freeze({dispose,drawScene(ctx,{camera,foot,facing,now,player,bits,foreground,visualOffset=[0,0]}){check();if(!Number.isInteger(bits)||bits<0||bits>7)throw Error('GYM8_BITS');
 const entries=ACTORS.map((a,i)=>({a,foot:i<3?SOURCE.poses[i][bits&(1<<i)?2:0]:SOURCE.leader.foot}));entries.push({foot,player:true});entries.sort((a,b)=>a.foot[1]-b.foot[1]);
 for(const e of entries){if(e.player)player.draw(ctx,{foot:[foot[0]-camera[0]+visualOffset[0],foot[1]-camera[1]+visualOffset[1]],facing,elapsedMs:now,moving:false});else{const f=e.a.frame,k=80/192;ctx.save();try{ctx.imageSmoothingEnabled=false;ctx.drawImage(images.get(e.a.id),...f.rect,e.foot[0]-camera[0]-f.anchor[0]*k,e.foot[1]-camera[1]-f.anchor[1]*k,f.width*k,f.height*k)}finally{ctx.restore()}}foreground(ctx,camera,e.foot[1]);check()}
 return true;
 }});
 }catch(e){close(pending);dispose();throw e}
}

